// Kiểm chữ ký X-Trinity-Signature (HMAC-SHA256 trên body THÔ) và lọc đúng loại sự kiện.
// Dán secret whsec_… (hiện một lần khi tạo endpoint ở Trinity: Cài đặt › Kết nối › Webhook ra).
const SECRET = 'whsec_DAN_SECRET_CUA_BAN_VAO_DAY';
const WANT = 'contact.created';
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers ?? {};
const sig = String(headers['x-trinity-signature'] ?? '');
const parts = Object.fromEntries(sig.split(',').map((p) => p.split('=')));
const t = Number(parts.t);
if (!t || Math.abs(Date.now() / 1000 - t) > 300) throw new Error('Chữ ký Trinity hết hạn hoặc thiếu');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', SECRET).update(`${t}.${raw}`).digest('hex');
const got = String(parts.v1 ?? '');
if (got.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected))) throw new Error('Sai chữ ký Trinity');

const evt = JSON.parse(raw);
if (evt.type === 'ping') return [];          // nút "Gửi thử" của Trinity
if (evt.type !== WANT) return [];            // endpoint có thể nhận nhiều loại sự kiện
return [{ json: { delivery_id: evt.id, ...{
  ten: evt.data.contact.full_name,
  sdt: evt.data.contact.phone,
  email: evt.data.contact.email,
  nguon: evt.data.origin ?? '',
  contact_id: evt.data.contact.id,
} } }];
